import{_ as n,C as r,o as a,c as s,a3 as t,b as d,w as o,a as h,E as l,a4 as c}from"./chunks/framework.DhF4LrUq.js";const C=JSON.parse(`{"title":"Authorization","description":"ShipperDog's authorization model - the seven-layer decision chain, grants, and the concealed 404.","frontmatter":{"description":"ShipperDog's authorization model - the seven-layer decision chain, grants, and the concealed 404."},"headers":[],"relativePath":"concepts/authorization.md","filePath":"concepts/authorization.md"}`),p={name:"concepts/authorization.md"};function u(m,e,g,b,A,y){const i=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h1><p>ShipperDog&#39;s design principle is explicit authorization: nobody can reach anything by default, and every decision is recorded. Two engines cooperate — one decides who may manage, the other decides what anyone may reach.</p><h2 id="roles-who-may-manage" tabindex="-1">Roles (who may manage) <a class="header-anchor" href="#roles-who-may-manage" aria-label="Permalink to &quot;Roles (who may manage)&quot;">​</a></h2><p>Console authority is role-based, evaluated live from the database on every request — role changes take effect immediately, never at the next token refresh. Organization roles, tenant roles, and the platform administrator flag feed one permission matrix. Plain membership grants nothing; every functional role earns specific capabilities (an <code>ORG_ADMIN</code> administers everything organization-wide; a <code>DEVELOPER</code> uploads artifacts; a <code>QA_ENGINEER</code> triages feedback and signs the QA step; and so on). Effective permissions are the union of every role a person holds.</p><h2 id="the-layered-decision-what-you-may-reach" tabindex="-1">The layered decision (what you may reach) <a class="header-anchor" href="#the-layered-decision-what-you-may-reach" aria-label="Permalink to &quot;The layered decision (what you may reach)&quot;">​</a></h2><p>Which applications a tester can see, which versions, which downloads — that is decided by a second engine that walks seven ordered layers, from the person down to the live distribution:</p>',6)),(a(),d(c,null,{default:o(()=>[l(i,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20START%5B%22A%20request%20reaches%20a%20resource%3Cbr%2F%3E(list%20apps%2C%20read%20a%20version%2C%20download)%22%5D%0A%20%20%20%20L1%7B%22USER%3Cbr%2F%3Esubject%20exists%22%7D%0A%20%20%20%20L2%7B%22ORGANIZATION%3Cbr%2F%3Eowning%20org%20exists%20and%20is%20ACTIVE%22%7D%0A%20%20%20%20L3%7B%22TENANT%3Cbr%2F%3Ehow%20does%20the%20subject%3Cbr%2F%3Ereach%20this%20tenant%3F%22%7D%0A%20%20%20%20L4%7B%22APPLICATION%3Cbr%2F%3Edoes%20the%20tenant%3Cbr%2F%3Ehave%20this%20app%3F%22%7D%0A%20%20%20%20L5%7B%22VERSION%3Cbr%2F%3Eis%20the%20version%20authorized%3F%3Cbr%2F%3E(lifecycle%20%2B%20entitlement%20grant)%22%7D%0A%20%20%20%20L6%7B%22ARTIFACT%3Cbr%2F%3Eis%20a%20distributable%20artifact%3Cbr%2F%3Eavailable%20for%20the%20platform%3F%22%7D%0A%20%20%20%20L7%7B%22DISTRIBUTION%3Cbr%2F%3Eis%20distribution%20active%3F%3Cbr%2F%3E(revocation%2C%20rollback%20cutoff)%22%7D%0A%20%20%20%20ABAC%7B%22ABAC%20refinement%3Cbr%2F%3Eorganization%20attribute%20policies%3Cbr%2F%3E(deny-only%2C%20optional)%22%7D%0A%20%20%20%20ALLOW%5B%22ALLOW%20%E2%80%94%20serve%20the%20resource%22%5D%0A%20%20%20%20DENY%5B%22DENY%20%E2%80%94%20concealed%20as%20the%20route's%3Cbr%2F%3Eordinary%20not-found%3B%20the%20reason%3Cbr%2F%3Egoes%20to%20the%20audit%20trail%20only%22%5D%0A%0A%20%20%20%20START%20--%3E%20L1%0A%20%20%20%20L1%20--%3E%7Cyes%7C%20L2%0A%20%20%20%20L2%20--%3E%7Cyes%7C%20L3%0A%20%20%20%20L3%20--%3E%7Creaches%7C%20L4%0A%20%20%20%20L4%20--%3E%7Cyes%7C%20L5%0A%20%20%20%20L5%20--%3E%7Centitled%7C%20L6%0A%20%20%20%20L6%20--%3E%7Cavailable%7C%20L7%0A%20%20%20%20L7%20--%3E%7Cactive%7C%20ABAC%0A%20%20%20%20ABAC%20--%3E%7Cno%20policy%20or%20passes%7C%20ALLOW%0A%20%20%20%20L1%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L2%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L3%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L4%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L5%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L6%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20L7%20--%3E%7Cno%7C%20DENY%0A%20%20%20%20ABAC%20--%3E%7C%22a%20DENY%2FREQUIRE%20policy%20fires%22%7C%20DENY%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>The first failing layer short-circuits the walk. The engine fails closed: a fault is a denial, never an allow.</p><h2 id="grants-how-testers-get-access" tabindex="-1">Grants: how testers get access <a class="header-anchor" href="#grants-how-testers-get-access" aria-label="Permalink to &quot;Grants: how testers get access&quot;">​</a></h2><p>Testers are not given roles — they are given <strong>version grants</strong>, and the grant shapes are deliberately simple:</p><table tabindex="0"><thead><tr><th>Shape</th><th>What it authorizes</th></tr></thead><tbody><tr><td>Explicit version</td><td>Exactly one named version</td></tr><tr><td>Application</td><td>Every version of the application the granting tenant can see</td></tr><tr><td>Tag</td><td>Every version carrying the tag (newly tagged versions join automatically)</td></tr><tr><td>Latest N</td><td>The N newest working-set versions — the window slides as builds arrive</td></tr></tbody></table><p>Grants compose with union semantics, can carry an expiry (evaluation time — expired grants never authorize but stay on record), and can be revoked or bulk-revoked with a mandatory reason. Revocation is a state flip, never a deletion: history stays, and it takes effect on the very next decision.</p><p>Two switches must both be on for a tester&#39;s access: the tester person record active, and the tenant membership active. Suspending either one denies every decision immediately.</p><h2 id="opaque-denials" tabindex="-1">Opaque denials <a class="header-anchor" href="#opaque-denials" aria-label="Permalink to &quot;Opaque denials&quot;">​</a></h2><p>A caller who is not authorized learns nothing: resource-scoped denials render as the byte-identical <code>404</code> a genuine miss produces. A tester who asks about a version they were never granted cannot distinguish &quot;does not exist&quot; from &quot;not yours&quot; — which check failed lives in the audit trail alone. This is deliberate (PRD 12): existence is itself information.</p><h2 id="the-decision-api" tabindex="-1">The decision API <a class="header-anchor" href="#the-decision-api" aria-label="Permalink to &quot;The decision API&quot;">​</a></h2><p>The tester portal rides three self-scoped endpoints that are decided by this engine and nothing else: the authorized application catalog, the authorized version history, and the download decision that mints short-lived signed URLs. The sets are computed server-side — never a client-side filter of a bigger list.</p><h2 id="abac-refinement" tabindex="-1">ABAC refinement <a class="header-anchor" href="#abac-refinement" aria-label="Permalink to &quot;ABAC refinement&quot;">​</a></h2><p>Organizations can author attribute-based policies — typed conditions over attributes like the caller&#39;s role, the application&#39;s name, the target environment, the ring being entered — with <code>DENY</code> and <code>REQUIRE</code> effects. ABAC can only narrow access: there is no allow outcome, and a policy no grant backs authorizes nothing. The same engine is consulted on ring promotions (&quot;can promote only when security gates pass&quot;), where refusals name the rule that fired.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/tenancy-isolation">Tenancy and isolation</a> — the dimensions the chain walks</li><li><a href="/shipperdog/snapshot/concepts/security-model">Security model</a> — what happens to decisions after they are made (audit, SIEM)</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/authorization.md" target="_blank" rel="noreferrer">authorization</a> module doc (the full role matrix, grant endpoints, the ABAC engine, the isolation test suite).</li></ul>',14))])}const E=n(p,[["render",u]]);export{C as __pageData,E as default};
